    h = pid_h * BH + tl.arange(0, BH)[:, None]

    w_f = w.to(tl.float32)
    h_f = h.to(tl.float32)
    Wf = W.to(tl.float32)
    Hf = H.to(tl.float32)

    # Step/FMA form matching the FlagGems reference: precompute reciprocal
    # scalars once per program so the per-lane hot path has no division.
