    t01 = tl.sum(tl.where(off6 == 1, t, 0.0))
    t02 = tl.sum(tl.where(off6 == 2, t, 0.0))
    t10 = tl.sum(tl.where(off6 == 3, t, 0.0))
    t11 = tl.sum(tl.where(off6 == 4, t, 0.0))
    t12 = tl.sum(tl.where(off6 == 5, t, 0.0))

    row0 = t00 * x + t01 * y + t02
    row1 = t10 * x + t11 * y + t12

    # One contiguous store: interleave x/y into the [N,H,W,2] layout so MTE3
    # writes a coalesced (BH, 2*BW) tile instead of two stride-2 stores.
